SELECT n.gender, rt.role, cn.name, COUNT(*)
FROM title as t, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt, movie_info as mi1, info_type as it, non_leaf_340
WHERE kt.id = non_leaf_340.t_kind_id AND (cn.name ILIKE '%warn%') AND (mi1.info ILIKE '%mon%') AND (rt.role IN ('actress','cinematographer','composer','costume designer','director','editor','guest','production designer')) AND it.id = non_leaf_340.mi1_info_type_id AND cn.id = mc.company_id AND mc.movie_id = non_leaf_340.t_id AND (kt.kind ILIKE '%m%') AND n.id = non_leaf_340.ci_person_id AND (it.id IN ('6')) AND mc.movie_id = non_leaf_340.ci_movie_id AND ct.id = mc.company_type_id AND (t.production_year >= 1875) AND (t.production_year <= 2015);